<template>
  <form class="form-user" ref="form">
    <span class="form-user__block" v-for="block in data" :key="block">
      <label class="form-user__label" :for="block.name">{{ block.label }}</label>
      <input class="form-user__input" type="text" :name="block.name" :id="block.name" :value="setValue( block.name )">
    </span>
  </form>
</template>

<script setup>
  import { ref, defineProps, defineExpose } from 'vue';

  const props = defineProps({
    data: {
      type: Array,
      required: true
    },

    active: {
      type: Object,
      required: false
    }
  })

  const form = ref( null )

  const setValue = ( key ) => props?.active ? props.active[ key ] : ''

  defineExpose({ form })
</script>