<template>
  <span v-if="lessons && lessons?.length > 0">
    <div class="lessons__container">
      <div class="lessons__inner" :style="{ transform: `translateX(-${ active * (600 + 40) }px)` }" v-if="lessons?.length">
        <vLesson 
          v-for="( lesson, index ) in lessons" :key="index" 
          :lesson="{ number: index + 1, index: lessons.length - index, ...lesson }"
        />
      </div>
    </div>
  
    <div class="lessons__container-btn">
      <button class="lessons__btn lessons__btn_next"  @click="nextLesson" v-show="active != lessons.length - 1" :disabled="active >= lessons.length - 1" >
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -960 960 960" fill="#e8eaed">
          <path d="m283.54-220 186.15-260-186.15-260h48.77l186.15 260-186.15 260h-48.77Zm231.84 0 186.16-260-186.16-260h48.77l186.16 260-186.16 260h-48.77Z"/>
        </svg>
      </button>
  
      <button class="lessons__btn lessons__btn_prev" @click="prevLesson" v-show="active != 0" :disabled="active <= 0">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -960 960 960" fill="#e8eaed">
          <path d="m283.54-220 186.15-260-186.15-260h48.77l186.15 260-186.15 260h-48.77Zm231.84 0 186.16-260-186.16-260h48.77l186.16 260-186.16 260h-48.77Z"/>
        </svg>
      </button>
    </div>
  </span>

  <p class="per-pass-tests__empty" v-else-if="lessons !== null && lessons?.length === 0">
    Список пуст. Простите но администратор сайта не добавил уроки...
  </p>

  <vLoader v-else-if="lessons === null" />
</template>

<script setup>
  import vLesson from '@/components/lessons/vLesson.vue';
  import vLoader from '@/components/loaders/vLoader.vue';
  
  import { ref, computed, onMounted } from 'vue';
  import { useStore } from 'vuex';

  const active = ref( 0 )

  const store = useStore()

  const nextLesson = () => {
    active.value++
  }
  const prevLesson = () => {
    active.value--
  }

  const lessons = computed( () => store.state.Lessons.lessons )

  onMounted(() => {
    store.dispatch( 'Lessons/getLessons' )
  })
</script>