<template>
  <div class="adm-users" v-if="users">
    <vFormAdmUsers :data="formData" v-if="active_form == 'create'" ref="create_form" />
    <vFormAdmUsers :data="formData" :active="active" v-else-if="active_form == 'update'" ref="update_form" />

    <vTable class="adm-users__table" :data="users" :head="head" @select="selectUser" v-else />

    <div class="per-pass-tests__container-tests adm-users__container-tests" v-if="tests && tests?.length > 0 && active_form == null">
      <vPassTest 
        v-for="( test, index ) in tests" :key="index"
        :section="'adm-pass-test'"
        :index="index"
        :test="test"
      />
    </div>  

    <div class="adm-users__container">
      <span class="adm-users__inner" v-if="active_form == 'create'">
        <button class="adm-users__btn" @click="createUser">Создать</button>
        <button class="adm-users__btn" @click="active_form = null">Отменить</button>
      </span>

      <span class="adm-users__inner" v-if="active_form == 'update'">
        <button class="adm-users__btn" @click="updateUser">Изменить</button>
        <button class="adm-users__btn" @click="active_form = null">Отменить</button>
      </span>

      <span class="adm-users__inner" v-if="active_form == null">
        <button class="adm-users__btn" @click="active_form = 'create'">Создать</button>

        <span class="adm-users__inner-db" v-if="active_form == null && active">
          <button class="adm-users__btn" @click="active_form = 'update'">Изменить</button>
          <button class="adm-users__btn" @click="deleteUser">Удалить</button>
          <p class="adm-users__active" v-if="active">Выбранный пользователь: <span class="active">{{ active.id }}</span></p>
        </span>
      </span>
    </div>
  </div>

  <vLoader v-else />
</template>

<script setup>
  import vFormAdmUsers from '@/components/forms/vFormAdmUsers';
  import vLoader from '@/components/loaders/vLoader';
  import vTable from '@/components/tables/vTable';

  import vPassTest from '@/components/tests/vPassTest';

  import { computed, onBeforeMount, ref, watch } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const tests = computed( () => store.state.Tests.passed_tests )

  const users = computed(() => store.state.Users.users )
  const active = ref( null )

  const create_form = ref( null )
  const update_form = ref( null )

  const active_form = ref( null )

  const formData = ref([
    { label: 'почту', name: 'email' },
    { label: 'пароль', name: 'password' },
    { label: 'телефон', name: 'phone' },
    { label: 'фамилию', name: 'first_name' },
    { label: 'имя', name: 'middle_name' },
    { label: 'отчество', name: 'last_name' },
    { label: 'номер группы', name: 'group_id' },
    { label: 'права', name: 'user_right' },
  ])

  const head = ref([
    'Номер',
    'Почта',
    'Пароль',
    'Телефон',
    'Права',
    'Фамилия',
    'Имя',
    'Отчество',
    'Группа'
  ])

  const validFormData = ( array, form_data ) => {
    const data = {}

    array.forEach( item => {
      if ( item && item.name ) {
        data[ item.name ] = form_data.get( item.name )?.trim() || '';
      }
    })

    return data
  }

  const createUser = async () => {
    const form = new FormData( create_form.value.form )
    const data = validFormData( formData.value, form )
    const res = await store.dispatch( 'Users/createUser', data )
    if( res == 'success' ) active_form.value = null
  }

  const updateUser = async () => {
    const form = new FormData( update_form.value.form )
    const data = validFormData( formData.value, form )
    const res = await store.dispatch( 'Users/updateUser', { 'id': active.value.id, ...data } )
    if( res == 'success' ) active_form.value = null
  }

  const deleteUser = async () => {
    const res = await store.dispatch( 'Users/deleteUser', { 'id': active.value.id } )
    if( res == 'success' ) {
      active_form.value = null
      active.value = null
    }
  }

  const selectUser = ( user ) => active.value = user

  onBeforeMount(() => {
    store.dispatch( 'Users/getAllUsers' )
  })

  watch( active_form, ( newCfg ) => {
    if( newCfg == 'create' || newCfg == 'update' ) store.commit( 'Tests/setState', false )
    else store.commit( 'Tests/setState', true )
  })

  watch( active, ( newCfg ) => {
    if( newCfg != null ) store.dispatch( 'Tests/getPassedTests', { 'user_id': active.value.id } )
  })
</script>