import { post } from "@/additional-classes/requests.js";

export default {
  namespaced: true,

  actions: {
    async getTests( { commit }, data ) {
      commit( 'clearTests' )

      const response = await post( 'get-tests', data )
      commit( 'setTests', response )

      if( response ) return 'success'
    },

    async getTest( { commit }, data ) {
      commit( 'clearTest' )
      
      const response = await post( 'get-test', data )
      commit( 'setTest', response )
    },

    async getAdmTest( { commit }, data ) {
      commit( 'clearTest' )
      
      const response = await post( 'get-adm-test', data )
      return { message: true, data: response }
    },

    async setPassedAnswer( { commit }, data ){
      const response = await post( 'set-passed-answer', data, commit, true )
      if( response ) return 'success'
    },

    async getPassedTests( { commit }, data ){
      const response = await post( 'get-passed-tests-result', data )
      commit( 'setPassedTests', response )
    },

    async getPassedTest( { commit }, data ){
      const response = await post( 'get-test-result', data )
      commit( 'setPassedTest', response )
    },
    
    async getAllTests( { commit } ){
      const response = await post( 'all-tests' )
      commit( 'setAdminTests', response )
    },

    async createTest( { commit }, data ){
      const response = await post( 'test-create', data, commit, true )
      if( response ) {
        commit( 'setAdminTests', response.data.original )
        return 'success'
      }
    },
    
    async updateTest( { commit }, data ){
      const response = await post( 'test-update', data, commit, true )
      if( response ) {
        console.log( response );
        commit( 'setAdminTests', response.data.original )
        return 'success'
      }
    },

    async deleteTest( { commit }, data ){
      const response = await post( 'test-delete', data, commit, true )
      if( response ) {
        commit( 'setAdminTests', response.data.original )
        return 'success'
      }
    },
  },

  mutations: {
    setHideAdmActiveSection( state, section ) {
      state.hide_adm_active_section = section
    },

    setActiveSection( state, section ) {
      state.active_section = section
    },

    setPassedTests( state, passed_tests ) {
      state.passed_tests = passed_tests
    },

    setPassedTest( state, passed_test ) {
      state.passed_test = passed_test
    },

    setPassedTestId( state, id ) {
      state.passed_test_id = id
    },

    clearPassedTest( state ) {
      state.passed_test = null
    },

    clearPassTestId( state ) {
      state.passed_test_id = null
    },

    setTests( state, tests ) {
      state.tests = tests
    },

    setTest( state, test ) {
      state.test = test
    },

    clearTests( state ) {
      state.tests = null
    },

    clearTest( state ) {
      state.test = null
    },

    setAdminTests( state, admin_tests ) {
      state.admin_tests = admin_tests
    },

    setState( state, new_state ) {
      state.state = new_state
    },
  },
  
  state: {
    hide_adm_active_section: null,
    active_section: 'user-info',

    passed_test_id: null,
    passed_tests: null,
    passed_test: null,
    tests: null,
    test: null,

    admin_tests: null,

    state: true
  },

  getters: {
    
  }
}