import { createRouter, createWebHashHistory } from 'vue-router';

/* components pages */ 
import PersonalInformationView from '@/pages/PersonalInformationView.vue';
import LessonsView from '@/pages/LessonsView.vue';
import LessonView from '@/pages/LessonView.vue';
import TestsView from '@/pages/TestsView.vue';
import AdminView from '@/pages/AdminView.vue';
import HomeView from '@/pages/HomeView.vue';
import TestView from '@/pages/TestView.vue';

const routes = [
  {
    component: HomeView,
    path: '/',
    name: 'home',
  },
  {
    component: LessonsView,
    path: '/lessons',
    name: 'lessons',
  },
  {
    component: LessonView,
    path: '/lesson/:id',
    name: 'lesson',
    props: true
  },
  {
    component: TestsView,
    path: '/tests',
    name: 'tests',
  },
  {
    component: TestView,
    path: '/test/:id',
    name: 'test',
    props: true
  },
  {
    component: PersonalInformationView,
    path: '/personal-information',
    name: 'personal-information',
  },
  {
    component: AdminView,
    path: '/admin',
    name: 'admin',
    meta: { requiresAuth: true, requiresAdmin: true }
  },
]

const router = createRouter({
  linkActiveClass: 'nav__link_active',
  history: createWebHashHistory(),
  routes
})

router.beforeEach( (to, from, next) => {
  let isAuthenticated = false;
  let isAdmin = false;
  let user = null;

  const requiresAuth = to.matched.some(record => record.meta.requiresAuth);
  const requiresAdmin = to.matched.some(record => record.meta.requiresAdmin);

  let data = localStorage.getItem( 'User' );

  if( data ) {
    try {
      user = JSON.parse( data );
      if( user && user.id ) isAuthenticated = true;
      if( user && user.user_right === 'admin' ) isAdmin = true;
    } catch (error) {
      console.error("Ошибка при парсинге данных из localStorage:", error);
    }
  }

  // console.log(`to: ${to.path}`, 'requiresAuth:', requiresAuth, 'requiresAdmin:', requiresAdmin, "isAuthenticated:", isAuthenticated, "isAdmin:", isAdmin);

  if (requiresAuth && !isAuthenticated) {
    next('/');
    return;
  }

  if (requiresAdmin && !isAdmin) {
    next('/');
    return;
  }

  next();
})


export default router