<template>
  <div 
    :class="['unit-test', { 'unit-test_disabled': test['passed-test'] }]"
    @click="!test['passed-test'] && navigateToTest()"
  >
    <h2 class="unit-test__title">{{ test.title }}</h2>
    <p class="unit-test__description">{{ test.description }}</p>
  </div>
</template>

<script setup>
  import { useRouter } from 'vue-router';
  import { defineProps } from 'vue';

  const props = defineProps({
    test: {
      type: Object,
      required: false,
    },
  });

  const router = useRouter()

  const navigateToTest = () => router.push( `/test/${ props.test.id }` ) 
</script>
