<template>
  <div class="answer">

    <form class="answer__container">
      <vRadio
        :class="{ 'input-field_active': selected?.id == answer.id }"
        v-for="answer in answers" :key="answer"
        @click="selectAnswer( answer )"
        :text="answer.text"
      />
    </form>
    
  </div>
</template>

<script setup>
  import vRadio from '@/components/inputs/vRadio';
  
  import { ref, defineProps, defineEmits } from 'vue';

  defineProps({
    answers: {
      type: Array,
      required: true
    }
  })

  const selected = ref( null )

  const emit = defineEmits([ 'select' ])

  const selectAnswer = ( answer ) => {
    selected.value?.id != answer.id ? selected.value = answer : selected.value = null
    emit( 'select', selected.value )
  }
</script>