<template>
  <div class="adm-users" v-if="group_tests">
    <vFormAdmUsers :data="formData" v-if="active_form == 'create'" ref="create_form" />
    <vFormAdmUsers :data="formData" :active="active" v-else-if="active_form == 'update'" ref="update_form" />

    <vTable class="adm-users__table" :data="group_tests" :head="head" @select="selectGroupTest" v-else />

    <div class="adm-users__container">
      <span class="adm-users__inner" v-if="active_form == 'create'">
        <button class="adm-users__btn" @click="createGroup">Создать</button>
        <button class="adm-users__btn" @click="active_form = null">Отменить</button>
      </span>

      <span class="adm-users__inner" v-if="active_form == 'update'">
        <button class="adm-users__btn" @click="updateGroup">Изменить</button>
        <button class="adm-users__btn" @click="active_form = null">Отменить</button>
      </span>

      <span class="adm-users__inner" v-if="active_form == null">
        <button class="adm-users__btn" @click="active_form = 'create'">Создать</button>

        <span class="adm-users__inner-db" v-if="active_form == null && active">
          <button class="adm-users__btn" @click="active_form = 'update'">Изменить</button>
          <button class="adm-users__btn" @click="deleteGroup">Удалить</button>
          <p class="adm-users__active" v-if="active">Выбранная группа: <span class="active">{{ active.id }}</span></p>
        </span>
      </span>
    </div>
  </div>

  <vLoader v-else />
</template>

<script setup>
  import vFormAdmUsers from '@/components/forms/vFormAdmUsers';
  import vLoader from '@/components/loaders/vLoader';
  import vTable from '@/components/tables/vTable';

  import { computed, onBeforeMount, ref, watch } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const group_tests = computed(() => store.state.GroupTests.group_tests )
  const active = ref( null )

  const create_form = ref( null )
  const update_form = ref( null )

  const active_form = ref( null )

  const formData = ref([
    { label: 'Заголовок', name: 'title' },
    { label: 'Описание', name: 'description' },
  ])

  const head = ref([
    'Номер',
    'Заголовок',
    'Описание',
  ])

  const validFormData = ( array, form_data ) => {
    const data = {}

    array.forEach( item => {
      if ( item && item.name ) {
        data[ item.name ] = form_data.get( item.name )?.trim() || '';
      }
    })

    return data
  }

  const createGroup = async () => {
    const form = new FormData( create_form.value.form )
    const data = validFormData( formData.value, form )
    const res = await store.dispatch( 'GroupTests/createGroupTests', data )
    if( res == 'success' ) active_form.value = null
  }

  const updateGroup = async () => {
    const form = new FormData( update_form.value.form )
    const data = validFormData( formData.value, form )
    const res = await store.dispatch( 'GroupTests/updateGroupTests', { 'id': active.value.id, ...data } )
    if( res == 'success' ) active_form.value = null
  }

  const deleteGroup = async () => {
    const res = await store.dispatch( 'GroupTests/deleteGroupTests', { 'id': active.value.id } )
    if( res == 'success' ) {
      active_form.value = null
      active.value = null
    }
  }

  const selectGroupTest = ( group ) => active.value = group

  onBeforeMount(() => {
    store.dispatch( 'GroupTests/getGroupTests' )
  })

  watch( active_form, ( newCfg ) => {
    if( newCfg == 'create' || newCfg == 'update' ) store.commit( 'Tests/setState', false )
    else store.commit( 'Tests/setState', true )
  })
</script>