import { post } from "@/additional-classes/requests.js"

export default {
  namespaced: true,

  actions: {
    async getGroupTests( { commit } ) {
      const response = await post( 'get-group-tests', null )
      console.log( response );
      if( response ) commit( 'setGroupTests', response )
    },

    async createGroupTests( { commit }, data ) {
      const response = await post( 'group-tests-create', data, commit, true )
      if( response ) {
        commit( 'setGroupTests', response.data.original )
        return 'success'
      }
    },

    async updateGroupTests( { commit }, data ) {
      const response = await post( 'group-tests-update', data, commit, true )
      if( response ) {
        commit( 'setGroupTests', response.data.original )
        return 'success'
      }
    },

    async deleteGroupTests( { commit }, data ) {
      const response = await post( 'group-tests-delete', data, commit, true )
      if( response ) {
        commit( 'setGroupTests', response.data.original )
        return 'success'
      }
    },
  },

  mutations: {
    setGroupTests( state, group_tests ) {
      state.group_tests = group_tests
    },
  },
  
  state: {
    group_tests: null,
    group_test: null
  },

  getters: {
    
  }
}