<template>
  <div :class="`message ${ notification.type }`" v-if="notification" @click="closePopup">

    <div class="message__content">
      <p :class="`message__text`">{{ status }}: {{ notification.message }}</p>
    </div>

  </div>
</template>

<script setup>
  import { computed, watch } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()
  
  const notification = computed(() => store.state.Messages.notification )

  let timeout = null

  watch( notification, () => {
    if( !timeout ) timeout = setTimeout( () => closePopup(), 4000 )
    else clearTimeout( timeout )
  })

  const closePopup = () => store.commit( 'Messages/delMessage' )

  const statusMap = {
    'success': 'Сообщение',
    'warning': 'Предупреждение',
    'error': 'Ошибка',
  }

  const status = computed( () => statusMap[ notification.value.type ] )
</script>