const backend_url = 'https://jususcode-backend.ru'

const post = async ( path, body = null, commit = null, message = null ) => {
  const options = {
    headers: { "Content-Type": "application/json" },
    method: 'POST',
  }

  if( body !== null ) options.body = JSON.stringify( body )

  const response = await fetch( `${backend_url}/${path}`, options )
  let data = await response.json()

  if( data?.error ) {
    commit( 'Messages/setMessage', { message: data.error[0], type: 'error' }, { root: true } ) 
    data = null
  } 
  else if( commit && typeof message === 'object'  ) commit( 'Messages/setMessage', message, { root: true } )
  else if( commit && message ) commit( 'Messages/setMessage', { message: data.message, type: 'success' }, { root: true } )

  return data
}

const upload = async ( path, body = null, commit = null, message = null ) => {
  const options = {
    method: 'POST',
  };

  if (body !== null) {
    options.body = body;
  }
  try {
    const response = await fetch( `${backend_url}/${path}`, options );

    if(!response.ok) {
      let data = await response.json()

      if ( data.errors ) {
        let errors = Object.values( data.errors ).flat();
        commit( 'Messages/setMessage', { message: errors.join(' '), type: 'error' }, { root: true } ) 
      }
      else if ( data.error ) commit( 'Messages/setMessage', { message: data.error.file, type: 'error' }, { root: true } )
      else {
        commit('Messages/setMessage', { message: 'Ошибка при запросе', type: 'error' }, {root: true})
      }
      return null;
    }

     let data = await response.json();

     if (data?.error) {
      if ( data.errors ) {
        let errors = Object.values( data.errors ).flat();
        commit( 'Messages/setMessage', { message: errors.join(' '), type: 'error' }, { root: true } ) 
      }
      else {
        commit('Messages/setMessage', { message: data.error.file, type: 'error' }, { root: true });
      }

      data = null;
    } else if (commit && typeof message === 'object') {
      commit('Messages/setMessage', message, { root: true });
    } else if (commit && message) {
      commit('Messages/setMessage', { message: data.message, type: 'success' }, { root: true });
    }

    return data;
  } catch (error) {
    console.error('Error in fetch:', error)
    commit('Messages/setMessage', { message: 'Ошибка при запросе', type: 'error' }, {root: true})
    return null;
  }
}


export { post, upload };