<template>
  <div class="per-user">
    <div class="per-user__photo-info">
      <span class="per-user__photo">
        <img :src="user.photo">
      </span>

      <div class="per-user__info-side">
        <p class="per-user__fml">Фио: <span class="active">{{ validFML }}</span></p>
        <p class="per-user__group">Дата создания: <span class="active">08.03.2024</span></p>
      </div>
    </div>

    <div class="per-user__info">
      <form class="per-user__form">
        <span class="per-user__block per-user__block_phone">
          <label for="phone">Телефон</label>
          <input type="text" id="phone" :value="validPhone">
        </span>
        <span class="per-user__block per-user__block_email">
          <label for="email">Почта</label>
          <input type="text" id="email" :value="user.email">
        </span>
        <span class="per-user__block per-user__block_pass">
          <label for="pass">Пароль</label>
          <input type="text" id="pass" :value="validPass">
        </span>
        <span class="per-user__block per-user__block_pass">
          <label for="pass">Группа</label>
          <input type="text" id="pass" :value="validGroup">
        </span>
        <span class="per-user__block per-user__block_pass">
          <label for="pass">Права</label>
          <input type="text" id="pass" :value="validRight">
        </span>
      </form>
    </div>
  </div>
</template>

<script setup>
  import { computed, ref } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const user = computed( () => store.state.Users.user )

  const userRight = {
    'user': 'Обычные',
    'moder': 'Расширенные',
    'admin': 'Администратор блэт',
  }

  const validRight = computed(() => userRight[ user.value.user_right ])

  const validGroup = computed(() => user.value?.group ? user.value.group : 'Не имеет группы' )

  const validFML = computed(() => {
    const f = user.value?.first_name || 'Пусто'
    const m = user.value?.middle_name || 'Пусто'
    const l = user.value?.last_name || 'Пусто'
    return `${ f } ${ m } ${ l }`
  })

  const showPass = ref( false )

  const validPhone = computed(() => {
    if (!user.value.phone) return 'Номера нет'
    const phoneNumber = user.value.phone.toString().replace(/\D/g, '')
    if (phoneNumber.length !== 11) return 'Некорректный номер телефона'

    return `+${phoneNumber.substring(0, 1)} (${phoneNumber.substring(1, 4)}) ${phoneNumber.substring(4, 7)}-${phoneNumber.substring(7, 9)}-${phoneNumber.substring(9, 11)}`
  });

  const validPass = computed(() => {
    if ( showPass.value || !user.value.password ) return user.value.password
    return '*'.repeat( user.value.password.length );
  });
</script>