<template>
  <div class="adm-lessons__container" v-if="file_list">
    <vFileUpload />

    <div class="adm-lessons__container_inner">
      <h2 class="adm-lessons__text">Файлы на сервере: </h2>

      <span 
        v-for="file in file_list" :key="file"
        class="adm-lessons__link" 
      >
        <a :href="file" target="_blank" class="adm-lessons__link">https://... {{ normalizeLink( file ) }}</a>
        <button class="adm-lessons__btn" @click="deleteFile( file )">Удалить файл</button>
      </span>
    </div>
  </div>

  <vLoader v-else />
</template>

<script setup>
  import vFileUpload from '@/components/forms/vFileUpload';

  import { computed, onBeforeMount } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const file_list = computed( () => store.state.Lessons.file_list )

  const deleteFile = async ( file ) => {
    const file_name = await normalizeLink( file )
    await store.dispatch( 'Lessons/deleteFile', { 'file_name': file_name } )
  }

  const normalizeLink = ( file ) => {
    const parts = file.split('/')
    const name = parts[ parts.length - 1 ]
    return name
  }

  onBeforeMount(() => {
    store.dispatch( 'Lessons/getFileList' )
  })
</script>