export default class Typing {
  constructor(el, words, time, looping, pause, callback) {
    this.el = el;
    this.words = words || [];
    this.time = time || 1;
    this.looping = looping || false;
    this.pause = pause || 1;
    this.currentWordIndex = 0;
    this.currentLetterIndex = 0;
    this.startTime = Date.now();
    this.callback = callback;
  }

  printWord = () => {
    if (this.currentWordIndex >= this.words.length) {
      if (this.looping) {
        this.currentWordIndex = 0;
        this.startTime = Date.now();
        this.printWord();
        return;
      }

      const endTime = Date.now();
      const renderTime = (endTime - this.startTime) / 1000;
      console.log(`Текст был отрисован за ${renderTime.toFixed(2)} секунд`);
      if (this.callback) {
        this.callback();
      }
      return;
    }

    const word = this.words[this.currentWordIndex];

    if (this.currentLetterIndex <= word.length) {
      this.el.textContent = word.substring(0, this.currentLetterIndex);
      this.currentLetterIndex++;
      setTimeout(this.printWord, this.time * 100);
    } else {
      this.currentLetterIndex = 0;
      this.currentWordIndex++;
      setTimeout(this.printWord, this.pause * 1000);
    }
  };

  start() {
    this.printWord();
  }
}