<template>
  <div class="login" v-if="!isLoading">
    <div class="login__info">
      <h1 class="login__title">\Сайт являеться приватным/</h1>
      <p class="login__description">Для получения доступа к сайту свяжитесь с создателем <span class="active">Serega the King OSETIA ALANIA BLIA</span>, по почте papayrus137@gmail.com или телефону +7 988 878 9368</p>
    </div>

    <form class="login__form" @submit.prevent="login( $event )">
      <span class="login__block">
        <label class="login__label">Введите имя</label>
        <input class="login__input" type="text" name="email">
      </span>
      
      <span class="login__block">
        <label class="login__label">Введите пароль</label>
        <input class="login__input" type="text" name="password">
      </span>

      <button class="login__btn">Войти</button>
    </form>
  </div>

  <vLoader v-else />
</template>

<script setup>
  import vLoader from '@/components/loaders/vLoader';

  import { useStore } from 'vuex';
  import { ref } from 'vue';

  const store = useStore()

  const isLoading = ref( false )
  
  const login = async ( event ) => {
    isLoading.value = true
    
    const form = new FormData( event.target )

    const data = { 
      email: form.get('email').trim(), 
      password: form.get('password').trim() 
    }

    const res = await store.dispatch( 'Users/login', data )
    if( res ) isLoading.value = false
  }
</script>