<template>
  <div class="answer">

    <form class="answer__container">
      <vBox
        :class="{ 'input-field_active': checkAnswer( answer ) }"
        v-for="answer in answers" :key="answer"
        @click="selectAnswer( answer )"
        :text="answer.text"
      />
    </form>
    
  </div>
</template>

<script setup>
  import vBox from '@/components/inputs/vBox';

  import { ref, defineProps, defineEmits } from 'vue';
  
  defineProps({
    answers: {
      type: Array,
      required: true
    }
  })

  const selected = ref( [] )

  const emit = defineEmits([ 'select' ])

  const selectAnswer = ( answer ) => {
    const index = selected.value.findIndex( el => el.id == answer.id )

    index !== -1 
      ? selected.value.splice( index, 1 )
      : selected.value.push( answer )

    emit( 'select', selected.value )
  }

  const checkAnswer = ( answer ) => selected.value.some( el => el.id == answer.id )
</script>