import { post, upload } from '@/additional-classes/requests.js';

export default {
  namespaced: true,

  actions: {
    async getLessons({ commit }) {
      commit( 'clearLessons' )
      
      const response = await post( 'get-all-lessons', null )
      commit( 'updateLessons', response )
    },

    async getLesson( { commit, dispatch }, id ) {
      commit( 'clearLesson' )

      const response = await post( 'get-lesson', { 'id': id } )
      dispatch( 'getText', response.test_file )
      commit( 'updateLesson', response )
    },

    async getText({ commit }, url) {
      const response = await fetch( url );
      const text = await response.text();
      commit( 'updateText', text )
    },

    async allLessons({ commit }) {
      const response = await post( 'all-lessons', null )
      commit( 'setAdmLessons', response )
    },

    async createLesson( { commit }, data ) {
      const response = await post( 'lesson-create', data, commit, true )
      if( response ) {
        commit( 'setAdmLessons', response.data.original )
        return 'success'
      }
    },

    async updateLesson( { commit }, data ) {
      const response = await post( 'lesson-update', data, commit, true )
      if( response ) {
        commit( 'setAdmLessons', response.data.original )
        return 'success'
      }
    },

    async deleteLesson( { commit }, data ) {
      const response = await post( 'lesson-delete', data, commit, true )
      if( response ) {
        commit( 'setAdmLessons', response.data.original )
        return 'success'
      }
    },

    async uploadText( { commit }, data ) {
      const response = await upload( 'lesson-upload-text', data, commit, true )
      commit( 'setFileList', response.data.original )
    },

    async getFileList( { commit } ) {
      const response = await post( 'lesson-file-list' )
      commit( 'setFileList', response )
    },
    
    async deleteFile( { commit }, data ) {
      const response = await post( 'lesson-file-delete', data, commit, true )
      commit( 'setFileList', response.data.original )
    }
  },

  mutations: {
    setAdmLessons( state, all_lessons ) {
      state.adm_lessons = all_lessons
    },

    setFileList( state, data ) {
      state.file_list = data.files
    },

    updateLessons( state, lessons ) {
      state.lessons = lessons
    },

    updateLesson( state, lesson ) {
      state.lesson = lesson
    },

    updateText( state, text ) {
      state.text = text
    },

    clearLessons( state ) {
      state.lessons = null
    },

    clearLesson( state ) {
      state.lesson = null
      state.text = null
    }
  },

  state: {
    adm_lessons: null,
    file_list: null,
    lessons: null,
    lesson: null,
    text: null
  },

  getters: {

  }
}