<template>
  <div class="question">
    <span>
      <h2 class="question__number">{{ question.index }}</h2>
      
      <span class="question__container">
        <p class="question__text">Вопрос: {{ questionText }}</p>
      </span>

      <pre class="question__code" v-if="code">
        <code v-html="highlightedCode"></code>
      </pre>
    </span>
    
    <component
      :is="getQuestionType( question.type )" 
      :answers="question.answers"
      @select="selectAnswer"
    />
  </div>
</template>

<script setup>
  import vSeveral from '@/components/answers/vSeveral';
  import vOne from '@/components/answers/vOne';

  import { defineProps, defineEmits, computed, watch, ref } from 'vue';
  import hljs from 'highlight.js';

  const props = defineProps({
    question: {
      type: Object,
      required: true
    }
  })
  
  const emit = defineEmits([ 'select' ])
  
  const componentMap = {
    'several-answers': vSeveral,
    'one-answer': vOne
  };

  const getQuestionType = ( type ) => componentMap[ type ]
  const selectAnswer = ( answer ) => emit( 'select', { id: props.question.id, text: props.question.text, answer: answer } )

  const codeAndText = computed(() => {
    const codeMatch = props.question.text.match(/<code>(.*?)<\/code>/)
    let code = codeMatch ? codeMatch[1] : null
    let text = props.question.text.replace(/<code.*?>(.*?)<\/code>/, '').trim()
    return { code, text }
  });

  const questionText = computed(() => codeAndText.value.text)
  const code = computed(() => codeAndText.value.code)
  const highlightedCode = ref(null)

  const formatCode = () => {
    if (!code.value) {
      highlightedCode.value = null
      return;
    }

    let formattedCode = code.value.replace(/<br\s*\/?>/gi, '\n')
    const highlighted = hljs.highlightAuto(formattedCode).value
    highlightedCode.value = highlighted.replace(/\n/g, '<br/>')
  };

  watch(code, () => {
    formatCode()
  }, { immediate: true })

</script>