import { createStore } from "vuex";

// Modules
import messages from "@/store/modules/messages";

import lessons from "@/store/modules/lessons";

import group_users from "@/store/modules/group_users";
import users from "@/store/modules/users";

import group_tests from "@/store/modules/group_tests";
import tests from "@/store/modules/tests";

const store = createStore({
  modules: {
    GroupUsers: group_users,
    GroupTests: group_tests,
    Messages: messages,
    Lessons: lessons,
    Users: users,
    Tests: tests,
  }
})

export default store;