<template>
  <span v-if="test && !isLoading">
    <div class="test-page__info">
      <h1 class="test-page__title">{{ test.title }}</h1>
      <p class="test-page__description">{{ test.description }}</p>
    </div>
  
    <div class="test-page__container-answer">
      <vQuestion 
        v-for="( question, index ) in test.questions" :key="index"
        :question="{ ...question, index: index + 1 }"
        @select="selectQuestion"
      />
    </div>
  
    <button class="home__btn test-page__btn" @click="endTest" v-if="testComplite">Закончить тест</button>
  </span>
    
  <vLoader v-else />
</template>

<script setup>
  import vQuestion from '@/components/questions/vQuestion';
  import vLoader from '@/components/loaders/vLoader';

  import { computed, ref, onMounted } from 'vue';
  import { useRoute, useRouter } from 'vue-router';
  import { useStore } from 'vuex';

  const isLoading = ref( false )

  const router = useRouter();

  const route = useRoute();
  const { id } = route.params;

  const store = useStore()

  const user = computed( () => store.state.Users.user )
  const test = computed( () => store.state.Tests.test )

  const answerQuestions = ref( [] )

  const testComplite = computed( () => test.value && test.value.questions.length ? answerQuestions.value.length === test.value.questions.length : null )

  const selectQuestion = ( selected ) => {    
    if( Array.isArray( selected.answer ) && selected.answer.length ) select( selected )
    else if( selected.answer?.id ) select( selected )
    else answerQuestions.value = answerQuestions.value.filter( el => el.id != selected.id )
  }

  const select = ( selected ) => {
    const index = answerQuestions.value.findIndex( el => el.id === selected.id )
  
    index !== -1
      ? answerQuestions.value[ index ] = selected
      : answerQuestions.value.push( selected )
  }

  onMounted( async () => {
    store.dispatch( 'Tests/getTest', { "user_id": user.value.id, "test_id": id } )
  })

  const endTest = async () => {
    isLoading.value = true

    await store.dispatch( 'Tests/setPassedAnswer', {
      "user_id": user.value.id,
      "test_id": test.value.id,
      "qa": answerQuestions.value
    })

    await store.dispatch( 'Tests/getTests', { "user_id": user.value.id, "test_id": test.value.id } )

    isLoading.value = false
    router.push('/tests')
  }
</script>