<template>
  <div class="tests__container" v-if="tests && tests?.length > 0">
    <component 
      v-for="item in tests" :key="item"
      :is="getTestType( item )"
      :test="item"
    />
  </div>

  <p class="per-pass-tests__empty" v-else-if="tests !== null && tests?.length === 0">
    Список пуст. Простите но администратор сайта не добавил тесты...
  </p>

  <vLoader v-else-if="tests === null" />
</template>

<script setup>
  import vLoader from '@/components/loaders/vLoader.vue';

  import vGroup from '@/components/tests/vGroup.vue';
  import vTest from '@/components/tests/vTest.vue';

  import { computed, onMounted } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const tests = computed( () => store.state.Tests.tests )
  const user = computed( () => store.state.Users.user )

  const componentMap = {
    'group': vGroup,
    'test': vTest
  };

  const getTestType = ( type ) => type?.list ? componentMap[ 'group' ]  : componentMap[ 'test' ]

  onMounted(() => {
    store.dispatch( 'Tests/getTests', { "user_id": user.value.id } )
  })
</script>