<template>
  <section class="passed-test">
    <div class="passed-test__container" v-if="test?.questions?.length">
      <div class="passed-test__info">
        <h1 class="passed-test__title">Тест: <span class="active">{{ test.title }}</span></h1>
        <p class="passed-test__description">Описание: {{ test.description }}</p>
        <p class="passed-test__percentage">
          Соотношение правильных ответов:
          
          <span :class="interestCheck( test.percentage_of_correct_answers )">
            {{ test.percentage_of_correct_answers }}%
          </span>
        </p>
      </div>
  
      <div class="passed-test__list">
        <VPassQuestion 
          v-for="( question, index ) in test.questions" :key="index"
          :question="question" 
          :index="index + 1"
        />
      </div>
    </div>

    <vLoader v-else />

    <div class="personal-information__container-btn personal-information__container-btn_hide" v-if="hide_active">
      <button class="personal-information__btn" @click="backToAdmUsers">
        Обратно
      </button>
    </div>
  </section>
</template>

<script setup>
  import VPassQuestion from '@/components/questions/vPassQuestion';
  import vLoader from '@/components/loaders/vLoader';

  import { computed, onBeforeMount } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const hide_active = computed( () => store.state.Tests.hide_adm_active_section )

  const user = computed( () => store.state.Users.user )
  const passedTestId = computed( () => store.state.Tests.passed_test_id )
  const test = computed( () => store.state.Tests.passed_test )

  const backToAdmUsers = () => {
    store.commit( 'Tests/setHideAdmActiveSection', null )
  }

  const interestCheck = ( procent ) => procent >= 50 ? procent >= 70 ? 'access': 'warning' : 'error'

  onBeforeMount(() => {
    store.dispatch( 'Tests/getPassedTest', { 'user_id': user.value.id, 'test_id': passedTestId.value } )
  })
</script>