<template>
  <div class="passed-answer">
    <p :class="[ 'passed-answer__text', answerColor( answer.state ) ]">{{ answer.text }}</p>
    <p class="passed-answer__selected" v-if="answer.passed">Выбранный</p>
  </div>
</template>

<script setup>
  import { defineProps } from 'vue';

  defineProps({
    answer: {
      type: Object,
      required: true
    }
  })

  const answerColor = ( state ) => state ? 'passed-answer__text_access' : 'passed-answer__text_error'
</script>