import { post } from "@/additional-classes/requests.js"

export default {
  namespaced: true,

  actions: {
    async login( { commit }, data ) {
      const response = await post( 'login', data, commit, true )
      if( response ) commit( 'setUser', response.data )
      return 'ok'
    },

    async getAllUsers( { commit } ) {
      const response = await post( 'all-users', null )
      if( response ) commit( 'setUsers', response )
    },

    async createUser( { commit }, data ) {
      const response = await post( 'user-create', data, commit, true )
      if( response ) {
        commit( 'setUsers', response.data.original )
        return 'success'
      }
    },

    async updateUser( { commit }, data ) {
      const response = await post( 'user-update', data, commit, true )
      if( response ) {
        commit( 'setUsers', response.data.original )
        return 'success'
      }
    },

    async deleteUser( { commit }, data ) {
      const response = await post( 'user-delete', data, commit, true )
      if( response ) {
        commit( 'setUsers', response.data.original )
        return 'success'
      }
    },
  },

  mutations: {
    setUsers( state, users ) {
      state.users = users
    },

    setUser( state, user ) {
      localStorage.setItem( 'User', JSON.stringify( user ) )
      state.user = user
    },

    localClearUser( state ) {
      localStorage.clear()
      state.user = null
    }
  },
  
  state: {
    users: null,
    user: null,
  },

  getters: {
    isAuthenticated: (state) => !!state.user,
    isAdmin: (state) => state.user?.user_right === 'admin',
  }
}