<template>
  <div class="form-test">
    <div class="form-test__info">
      <input class="form-test__input form-test__input_title" v-model="testData.title" type="text" placeholder="Название теста">
      <textarea class="form-test__textarea form-test__textarea_description" v-model="testData.description" placeholder="Описание" rows="3" />
    </div>

    <div class="form-test__console">
      <input class="form-test__input form-test__input_group" v-model="testData.group_test_id" type="text" placeholder="Номер группы">
      <button class="form-test__btn form-test__btn_console" @click="newQuestion">Добавить вопрос</button>
      <button class="form-test__btn form-test__btn_console form-test__btn_console-end" @click="clear">Очистить все</button>
      <button class="form-test__btn form-test__btn_console form-test__btn_console-end" @click="close">Отменить</button>
      <button class="form-test__btn form-test__btn_console form-test__btn_console-end" @click="select">{{ textBtn }}</button>
    </div>
    
    <div 
      v-for="( question, questionIndex ) in testData.questions" :key="questionIndex"
      class="form-test__question"
    >
      <span class="form-test__question-title">
        <textarea 
          class="form-test__textarea form-test__textarea_question-title" 
          :placeholder="'Вопрос ' + (questionIndex + 1)" 
          v-model="question.text" 
        />
      </span>

      <span class="form-test__question-console">
        <select class="form-test__select" v-model="question.type">
          <option value="one-answer">Один правильный ответ</option>
          <option value="several-answers">Несколько правильных ответов</option>
        </select>

        <button class="form-test__btn form-test__btn_question" @click.prevent="newAnswer( questionIndex )">Добавить ответ</button>
        <button class="form-test__btn form-test__btn_question" @click.prevent="delQuestion( questionIndex )">Удалить вопрос</button>
      </span>
      
      <div class="form-test__container-answer">
        <div 
          v-for="( answer, answerIndex ) in question.answers" :key="answerIndex"
          class="form-test__answer"
        >
          <span class="form-test__answer-title">
            <textarea 
              class="form-test__textarea form-test__textarea_answer-title" 
              :placeholder="'Ответ ' + (answerIndex + 1)" 
              v-model="answer.text" 
            />
          </span>

          <span class="form-test__answer-console">
            <label :class="answerClass( question, answer, answerIndex)">
              <input
                type="radio"
                v-if="question.type === 'one-answer'"
                :name="`question-${questionIndex}`"
                :value="answerIndex"
                v-model="question.selectedAnswer"
              />
              
              <input
                type="checkbox"
                v-if="question.type === 'several-answers'"
                :value="answerIndex"
                :checked="answer.state === 'right-answer'"
                @change="handleCheckboxChange( question, answer, $event )"
              />

              Правильный ответ
            </label>

            <button class="form-test__btn form-test__btn_answer" @click.prevent="delAnswer( questionIndex, answerIndex )">Удалить ответ</button>
          </span>
        </div>
      </div>

    </div>
  </div>
</template>

<script setup>
  import { ref, defineEmits, defineProps, onMounted, computed, watchEffect } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const user = computed( () => store.state.Users.user )

  const props = defineProps({
    id: {
      type: Number,
      required: false
    }
  })

  const emit = defineEmits([ 'select', 'close' ])

  const textBtn = computed( () => props?.id ? 'Обновить тест' : 'Сохранить тест' )

  const testData = ref({
    title: '',
    description: '',
    group_test_id: null,
    questions: []
  })

  const clear = () => {
    testData.value = {
      title: '',
      description: '',
      group_test_id: null,
      questions: []
    }
  }

  const newQuestion = () => {
    testData.value.questions.push({
      text: '',
      type: 'one-answer',
      answers: [{
        text: '',
        state: null
      }],
      selectedAnswer: null
    });
  }

  const delQuestion = (index) => {
    testData.value.questions.splice(index, 1);
  }

  const newAnswer = ( questionIndex ) => {
    testData.value.questions[ questionIndex ].answers.push({
      text: '',
      state: null
    })
  }

  const delAnswer = ( questionIndex, answerIndex ) => {
    testData.value.questions[ questionIndex ].answers.splice(answerIndex, 1);
  }

  const close = () => emit( 'close' )

  const select = () => {
    const data = JSON.parse(JSON.stringify(testData.value))

    data.questions.forEach( question => {
      question.answers.forEach( answer => {
        if (question.type === 'one-answer') {
          answer.state = null;
          if (question.answers.indexOf(answer) === question.selectedAnswer) {
            answer.state = 'right-answer'
          }
        } else if (question.type === 'several-answers') {
          if (answer.state === true || answer.state === 'right-answer') {
            answer.state = 'right-answer'
          } else {
            answer.state = null
          }
        }
      })

      delete question.selectedAnswer
    })
    
    // console.log( data );

    emit('select', { ...data });
  }


  const answerClass = (question, answer, answerIndex) => {
    let classes = ['form-test__answer-check'];
    if (question.type === 'one-answer') {
      if (answer.state === 'right-answer' || answerIndex === question.selectedAnswer) {
        classes.push('form-test__answer-check_active')
      }
    } else if( question.type === 'several-answers' ) {
      if ( answer.state === 'right-answer' ) {
        classes.push('form-test__answer-check_active')
      }
    }

    return classes;
  }
  
  onMounted( async () => {
    if ( props?.id && user.value.id ) {
      const res = await store.dispatch( 'Tests/getAdmTest', { 'test_id': props.id, 'user_id': user.value.id } )
      
      let result = null
      if( res?.message ) result = res.data

      if ( result ) {
        testData.value = result
        
        testData.value.questions.forEach( question => {
          if( question.type === 'one-answer' ) {
            question.answers.forEach( ( answer, answerIndex ) => {
              if( answer.state === 'right-answer' ) {
                question.selectedAnswer = answerIndex
              }
            })
          } else if( question.type === 'several-answers' ) {
            question.answers.forEach( ( answer ) => {
              if (answer.state === true ) {
                answer.state = 'right-answer'
              }
            })
          }
        })
      }
    }
  })

  watchEffect(() => {
    testData.value.questions.forEach(question => {
      if (question.type === 'one-answer' && question.selectedAnswer !== null) {
        question.answers.forEach((answer, answerIndex) => {
          if (answerIndex === question.selectedAnswer) {
            answer.state = 'right-answer';
          } else {
            answer.state = null;
          }
        });
      }
    });
  });

  const handleCheckboxChange = ( question, answer, event ) => {
    answer.state = event.target.checked ? 'right-answer' : null;
  }
</script>