<template>
  <div class="per-pass-tests__container-tests" v-if="tests && tests?.length > 0">
    <vPassTest 
      v-for="( test, index ) in tests" :key="index"
      :index="index"
      :test="test"
    />
  </div>

  <p class="per-pass-tests__empty" v-else-if="tests !== null && tests?.length === 0">
    Список пуст. Вы не прошли не одного теста...
  </p>

  <vLoader v-else-if="tests === null" />
</template>

<script setup>
  import vPassTest from '@/components/tests/vPassTest';
  import vLoader from '@/components/loaders/vLoader';

  import { computed, onMounted } from 'vue';

  import { useStore } from 'vuex';
  const store = useStore()

  const user = computed( () => store.state.Users.user )
  const tests = computed( () => store.state.Tests.passed_tests )

  onMounted(() => {
    store.dispatch( 'Tests/getPassedTests', { 'user_id': user.value.id } )
  })
</script>