<template>
  <component :is="getQuestionType( active )"/>

  <div class="personal-information__container-btn" v-if="!passedTestId">
    <button 
      @click="backToUserInfo" 
      :class="[ 
        { 'personal-information__btn_active': active == 'user-info' },
        'personal-information__btn'
      ]"
    >
      Данные пользователя
    </button>

    <button 
      @click="backToPasTests" 
      :class="[ 
        { 'personal-information__btn_active': active == 'passed-tests' },
        'personal-information__btn'
      ]"
    >
      Пройденные тесты
    </button>
  </div>

  <div class="personal-information__container-btn" v-else>
    <button class="personal-information__btn" @click="backToPasTests">
      Вернуться к списку
    </button>
  </div>
</template>

<script setup>
  import vPerUserInfo from '@/components/sections/vPerUserInfo';
  import vPerPasTests from '@/components/sections/vPerPasTests';
  import vPerAdvTest from '@/components/sections/vPerAdvTest';

  import { computed, onBeforeMount } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const active = computed( () => store.state.Tests.active_section )
  const passedTestId = computed( () => store.state.Tests.passed_test_id )

  const backToPasTests = () => {
    store.commit( 'Tests/clearPassTestId' )
    store.commit( 'Tests/setActiveSection', 'passed-tests' )
  }

  const backToUserInfo = () => {
    store.commit( 'Tests/clearPassTestId' )
    store.commit( 'Tests/setActiveSection', 'user-info' )
  }

  const componentMap = {
    'adv-pass-test': vPerAdvTest,
    'passed-tests': vPerPasTests,
    'user-info': vPerUserInfo,
  };

  const getQuestionType = ( type ) => componentMap[ type ]

  onBeforeMount(() => {
    backToUserInfo()
  })
</script>