import { post } from "@/additional-classes/requests.js"

export default {
  namespaced: true,

  actions: {
    async getGroupUsers( { commit } ) {
      const response = await post( 'get-group-users', null )
      console.log( response );
      if( response ) commit( 'setGroupUsers', response )
    },

    async createGroupUsers( { commit }, data ) {
      const response = await post( 'group-users-create', data, commit, true )
      if( response ) {
        commit( 'setGroupUsers', response.data.original )
        return 'success'
      }
    },

    async updateGroupUsers( { commit }, data ) {
      const response = await post( 'group-users-update', data, commit, true )
      if( response ) {
        commit( 'setGroupUsers', response.data.original )
        return 'success'
      }
    },

    async deleteGroupUsers( { commit }, data ) {
      const response = await post( 'group-users-delete', data, commit, true )
      if( response ) {
        commit( 'setGroupUsers', response.data.original )
        return 'success'
      }
    },
  },

  mutations: {
    setGroupUsers( state, group_users ) {
      state.group_users = group_users
    },
  },
  
  state: {
    group_users: null,
    group_user: null
  },

  getters: {
    
  }
}