<template>
  <div class="adm-users" v-if="tests">
    <vFormAdmTests v-if="active_form == 'create'" @select="createTest" @close="active_form = null" />
    <vFormAdmTests v-else-if="active_form == 'update'" @select="updateTest" @close="active_form = null" :id="active.id" />

    <vTable class="adm-users__table" :data="tests" :head="head" @select="selectTest" v-else />

    <div class="adm-users__container">
      <span class="adm-users__inner" v-if="active_form == null">
        <button class="adm-users__btn" @click="active_form = 'create'">Создать</button>

        <span class="adm-users__inner-db" v-if="active_form == null && active">
          <button class="adm-users__btn" @click="active_form = 'update'">Изменить</button>
          <button class="adm-users__btn" @click="deleteTest">Удалить</button>
          <p class="adm-users__active" v-if="active">Выбранный тест: <span class="active">{{ active.id }}</span></p>
        </span>
      </span>
    </div>
  </div>

  <vLoader v-else />
</template>

<script setup>
  import vFormAdmTests from '@/components/forms/vFormAdmTests';
  import vLoader from '@/components/loaders/vLoader';
  import vTable from '@/components/tables/vTable';

  import { computed, onBeforeMount, ref, watch } from 'vue';
  import { useStore } from 'vuex';

  const store = useStore()

  const tests = computed(() => store.state.Tests.admin_tests )
  const active = ref( null )

  const active_form = ref( null )

  const head = ref([
    'Номер',
    'Название',
    'Описание',
    'Группа'
  ])

  const createTest = async ( data ) => {
    const res = await store.dispatch( 'Tests/createTest', data )
    if( res == 'success' ) active_form.value = null
  }

  const deleteTest = async () => {
    const res = await store.dispatch( 'Tests/deleteTest', { 'id': active.value.id } )
    if( res == 'success' ) {
      active_form.value = null
      active.value = null
    }
  }

  const updateTest = async ( data ) => {
    const res = await store.dispatch( 'Tests/updateTest', { 'id': active.value.id, ...data } )
    if( res == 'success' ) active_form.value = null
  }

  const selectTest = ( test ) => active.value = test

  onBeforeMount(() => {
    store.dispatch( 'Tests/getAllTests' )
  })

  watch( active_form, ( newCfg ) => {
    if( newCfg == 'create' || newCfg == 'update' ) store.commit( 'Tests/setState', false )
    else store.commit( 'Tests/setState', true )
  })
</script>