<template>
  <div 
    :class="[ 'per-pass-tests__test', { 'per-pass-tests__test_active': showTable } ]"
  >
    <div 
      :class="[ 'per-pass-tests__info', { 'per-pass-tests__info_active': showTable } ]"
      @click="showTable = true"
    >
      <p class="per-pass-tests__test-title">
        {{ index + 1 }}. Тест: <span class="active">{{ test.title }}</span>
      </p>

      <p class="per-pass-tests__test-result">
        Общая оценка:

        <span :class="interestCheck( test.percentage_of_correct_answers )">
          {{ setScore( test.percentage_of_correct_answers ) }}
        </span>
        
        (
        <span :class="interestCheck( test.percentage_of_correct_answers )">
          {{ test.percentage_of_correct_answers }}%
        </span>
        )
      </p>
    </div>

    <div class="per-pass-tests__content" v-if="showTable">
      <vTable class="per-pass-tests__table" :data="test.questions" :head="head" />

      <span>
        <button class="per-pass-tests__btn" @click="toPassedTest">Развернуть</button>
        <button class="per-pass-tests__btn" @click="showTable = false">Скрыть</button>
      </span>
    </div>
  </div>
</template>

<script setup>
  import vTable from '@/components/tables/vTable';

  import { ref, defineProps } from 'vue';
  import { useStore } from 'vuex';
  
  const store = useStore()
  
  const showTable = ref( false )

  const props = defineProps({
    test: {
      type: Object,
      required: true
    },

    index: {
      type: Number,
      required: true
    },

    section: {
      type: String,
      required: false
    }
  })

  const toPassedTest = () => {
    if( props?.section ) {
      store.commit( 'Tests/clearPassedTest' )
      store.commit( 'Tests/setPassedTestId', props.test.id )
      store.commit( 'Tests/setHideAdmActiveSection', 'adm-pass-test' )
    } else {
      store.commit( 'Tests/clearPassedTest' )
      store.commit( 'Tests/setPassedTestId', props.test.id )
      store.commit( 'Tests/setActiveSection', 'adv-pass-test' )
    }
  }

  const head = ref([
    'Номер',
    'Вопрос',
    'Ответ'
  ])

  const interestCheck = ( procent ) => procent >= 50 ? procent >= 70 ? 'access': 'warning' : 'error'

  const setScore = ( procent ) => {
    return procent > 20 
      ? procent > 40
        ? procent > 60 
          ? procent > 80 
            ? 5
            : 4
          : 3
        : 2
      : 1
  }
</script>