import Typing from '../additional-classes/Typing';

export default {
  mounted(el, binding) {
    const { words, time, looping, pause, callback } = binding.value || {
      words: [],
      time: 1,
      looping: false,
      pause: 1,
    };
    const typing = new Typing(el, words, time, looping, pause, callback);
    typing.start();
  },
};