<template>
  <span v-if="lesson">
    <div class="lesson__info">
      <h1 class="lesson__title">{{ lesson.title }}</h1>
      <p class="lesson__description">{{ lesson.description }}</p>
    </div>

    <div class="lesson__loader" v-if="!lessonText">Загрузка блоков...</div>

    <div v-else class="lesson__content">
      <template v-for="(item, index) in parsedText" :key="index">
        <h2 v-if="item.tag === 'title'" >#{{item.content}}</h2>

        <p v-else-if="item.tag === 'block'" v-html="item.content"></p>
        <li v-else-if="item.tag === 'item'"><span v-html="item.content"></span></li>

        <table v-else-if="item.tag === 'tableData'">
          <thead>
            <tr>
              <th v-for="(header, headerIndex) in item.content.headers" :key="headerIndex">{{ header }}</th>
            </tr>
          </thead>
          
          <tbody>
            <tr v-for="(row, rowIndex) in item.content.rows" :key="rowIndex">
              <td v-for="(cell, cellIndex) in row" :key="cellIndex">{{ cell }}</td>
            </tr>
          </tbody>
        </table>

        <pre v-else-if="item.tag === 'code'">
          <code v-highlight :class="'hljs'">{{item.content}}</code>
        </pre>
      </template>
    </div>
  </span>

  <vLoader v-else />
</template>

<script setup>
  import vLoader from '@/components/loaders/vLoader.vue';
  
  import { defineProps, computed, onMounted } from 'vue';
  import { useStore } from 'vuex';

  const props = defineProps({
    id: {
      type: String,
      required: true,
    },
  })

  const store = useStore()

  const lesson = computed(() => store.state.Lessons.lesson )
  const lessonText = computed(() => store.state.Lessons.text )

  const parseLessonText = (text) => {
    if (!text) return [];

    const regex = /<(title|block|item|code|tableData)>(.*?)<\/\1>/gs;
    const result = [];
    let match;

    while ((match = regex.exec(text)) !== null) {
      const tag = match[1];
      let content = match[2].trim();

      try {
        if (tag === 'tableData') content = JSON.parse(content);
      } catch (error) {
        console.error('Error parsing table data', error);
        content = null;
      }
      
      result.push({ tag, content });
    }
    return result;
  };

  const parsedText = computed(() => parseLessonText(lessonText.value));

  onMounted( async () => {
    store.dispatch( 'Lessons/getLesson', props.id )
  });
</script>