<template>
  <form class="form-file" enctype="multipart/form-data" @submit.prevent="uploadData">
    <input class="form-file__input" type="file" name="file" id="file" accept=".txt" multiple ref="input" @change="updateFileName" required>
    
    <label class="form-file__label" for="file">
      <p>Нажми чтобы выбрать файл</p>
    </label>

    <span class="form-file__container">
      <p class="form-file__title">Выбранный файл: {{ fileName }}</p>
      <button class="form-file__btn" type="submit">Загрузить</button>
      <button class="form-file__btn form-file__btn_end" @click.prevent="clearFile">Удалить выбранный файл</button>
    </span>
  </form>
</template>

<script setup>
  import { useStore } from 'vuex';
  import { ref } from 'vue';

  const store = useStore()
  const input = ref( null )

  const fileName = ref( 'Файл не выбран' )

  const updateFileName = () => {
    if ( input.value.files.length > 0 ) fileName.value = input.value.files[0].name;
    else fileName.value = 'Файл не выбран';
  }

  const clearFile = () => {
    input.value.value = null;
    fileName.value = 'Файл не выбран';
  }

  const uploadData = () => {
    const formData = new FormData();
    formData.append('file', input.value.files[0]);
    store.dispatch('Lessons/uploadText', formData);
  };
</script>
