<template>
  <div class="passed-question">
    <span>
      <h2 class="passed-question__number">{{ index }}</h2>
      
      <span class="passed-question__container">
        <p class="passed-question__text">Вопрос: {{ questionText }}</p>

        <span class="small opacity">
          ( <span :class="questionColor( question.state )">{{ question.state }}</span> )
        </span>
      </span>

      <pre class="passed-question__code" v-if="code">
        <code v-html="highlightedCode"></code>
      </pre>
    </span>
    
    <div class="passed-question__container-answers">
      <VPassAnswer
        v-for="answer in question.answers" :key="answer"
        :answer="answer"
      />
    </div>
  </div>
</template>

<script setup>
  import VPassAnswer from '@/components/answers/vPassAnswer';

  import { ref, computed, watch, defineProps } from 'vue';
  import hljs from 'highlight.js';

  const props = defineProps({
    question: {
      type: Object,
      required: true
    },

    index: {
      type: Number,
      required: true
    }
  })

  const colorMap = {
    'Ответ правильный': 'access',
    'Ответ почти правильный': 'warning',
    'Ответ не правильный': 'error'
  }

  const questionColor = ( state ) => colorMap[ state ]

  const codeAndText = computed(() => {
    const codeMatch = props.question.text.match(/<code>(.*?)<\/code>/)
    let code = codeMatch ? codeMatch[1] : null
    let text = props.question.text.replace(/<code.*?>(.*?)<\/code>/, '').trim()
    return { code, text }
  });

  const questionText = computed(() => codeAndText.value.text)
  const code = computed(() => codeAndText.value.code)
  const highlightedCode = ref(null)

  const formatCode = () => {
    if (!code.value) {
      highlightedCode.value = null
      return;
    }

    let formattedCode = code.value.replace(/<br\s*\/?>/gi, '\n')
    const highlighted = hljs.highlightAuto(formattedCode).value
    highlightedCode.value = highlighted.replace(/\n/g, '<br/>')
  };

  watch(code, () => {
    formatCode()
  }, { immediate: true })
</script>